    if ($c.util.getComponent('ipt_langTpCd').getValue() === "1") {
        (($c.util.getComponent('ipt_onlyEng')) && ($c.util.getComponent('ipt_onlyEng')).setValue ? ($c.util.getComponent('ipt_onlyEng')).setValue((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    }
    if ('Y' === scwin.mon) {
        scwin.mon = 2;
    } else {
        scwin.mon = 1;
    }
    console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDatesOnlyPeriod(' + "scwin.mon" + ')');
